head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSecugrpID = "";
scwin.notiId;
scwin.strBzProcsNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        scwin.strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003_FILELIST.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_userlist_OnDblClick
 * @description grd_userlist 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_OnDblClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            $c.elw.fn_filedown(dts_fileList.getCellData(row, "SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05003_FILELIST.grd_userlist_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup(); // self.close();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003_FILELIST.btn_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_fileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.filedown = async function(attach_seq) {
    if (dts_fileList.getCellData(1, "FILE_SIZE") === 0) {
        await $c.win.alert("실제 파일이 존재하지 않습니다.");
    } else {
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF05003_FILELIST.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + scwin.strBzProcsNo + "&attach_seq=" + attach_seq + "&gubun=14";
    }
};

/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};
